"use client"

interface DistributionData {
  v0_samples?: number[]
}

export default function DistributionPlot({ data }: { data: DistributionData }) {
  const samples = data?.v0_samples || []

  if (!Array.isArray(samples) || samples.length === 0) {
    return (
      <div className="h-64 bg-slate-50 rounded flex items-center justify-center text-muted-foreground">
        No distribution data
      </div>
    )
  }

  // Simple histogram
  const bins = 20
  const min = Math.min(...samples)
  const max = Math.max(...samples)
  const binWidth = (max - min) / bins

  const histogram = Array(bins).fill(0)
  samples.forEach((val) => {
    const binIndex = Math.min(Math.floor((val - min) / binWidth), bins - 1)
    if (binIndex >= 0) histogram[binIndex]++
  })

  const maxCount = Math.max(...histogram)
  const barWidth = 100 / bins

  return (
    <div className="w-full space-y-4">
      <div className="flex items-end gap-0.5 h-48 bg-slate-50 p-4 rounded">
        {histogram.map((count, i) => (
          <div
            key={i}
            className="flex-1 bg-primary rounded-t"
            style={{ height: `${(count / maxCount) * 100}%`, minHeight: "2px" }}
            title={`Bin ${i}: ${count} samples`}
          />
        ))}
      </div>
      <div className="text-xs text-muted-foreground space-y-1">
        <p>Total Samples: {samples.length}</p>
        <p>
          Range: [{min.toFixed(2)}, {max.toFixed(2)}]
        </p>
      </div>
    </div>
  )
}
