"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import WaveformViewer from "@/components/waveform-viewer"
import PerformanceMetrics from "@/components/performance-metrics"
import DistributionPlot from "@/components/distribution-plot"

const exampleNetlist = `V1 in 0 SIN(0 10 50)
R1 in 1 1k
R2 1 2 1k
L1 2 0 1mH
C1 1 0 6u
.tran 20m 0 0.01m
.END`

function makeDemoWave(tCount = 500) {
  const t = Array.from({ length: tCount }, (_, i) => i * 0.04)
  const vin = t.map((tt) => 10 * Math.sin(2 * Math.PI * 50 * (tt / 1000)))
  const v0_healthy = vin.map((v, i) => 0.6 * v * Math.exp(-i / 500))
  const v0s = { healthy: v0_healthy }
  for (let e = 1; e <= 5; e++) {
    v0s["E" + e] = v0_healthy.map((v, i) => v * (1 - 0.1 * e) + (Math.random() - 0.5) * 0.2)
  }
  const v1_healthy = vin.map((v, i) => 0.4 * v * Math.exp(-i / 700))
  const v1s = { healthy: v1_healthy }
  for (let e = 1; e <= 5; e++) {
    v1s["E" + e] = v1_healthy.map((v, i) => v * (1 - 0.08 * e) + (Math.random() - 0.5) * 0.15)
  }
  return { t, vin, v0s, v1s }
}

export default function FaultDetectionApp() {
  const [netlist, setNetlist] = useState(exampleNetlist)
  const [running, setRunning] = useState(false)
  const [result, setResult] = useState(null)
  const [demo] = useState(makeDemoWave())

  const emptyResult = {
    classification: { label: "N/A", confidence: 0 },
    waveforms: {
      t: demo.t,
      vin: demo.vin,
      v0_healthy: demo.v0s.healthy,
      v0_E1: demo.v0s.E1,
      v0_E2: demo.v0s.E2,
      v0_E3: demo.v0s.E3,
      v0_E4: demo.v0s.E4,
      v0_E5: demo.v0s.E5,
      v1_healthy: demo.v1s.healthy,
      v1_E1: demo.v1s.E1,
      v1_E2: demo.v1s.E2,
      v1_E3: demo.v1s.E3,
      v1_E4: demo.v1s.E4,
      v1_E5: demo.v1s.E5,
    },
    metrics: {
      accuracy: 0.88,
      per_class: { E0: 0.9, E1: 0.85, E2: 0.87, E3: 0.86, E4: 0.9, E5: 0.83 },
      confusion: [
        [45, 1, 0, 2, 1, 1],
        [2, 43, 3, 0, 1, 1],
        [0, 2, 44, 2, 1, 1],
        [1, 0, 2, 46, 0, 1],
        [1, 1, 1, 0, 45, 2],
        [2, 1, 0, 1, 1, 45],
      ],
    },
    distribution: { v0_samples: demo.v0s.healthy },
  }

  async function handleClassify() {
    setRunning(true)
    try {
      const payload = { netlist }
      let resJson = null
      try {
        const resp = await fetch("/api/classify", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        })
        if (!resp.ok) throw new Error("Backend returned non-OK")
        resJson = await resp.json()
        if (!resJson || !resJson.waveforms || !Array.isArray(resJson.waveforms.t)) {
          throw new Error("Invalid response shape from backend")
        }
      } catch (err) {
        const demoLabel = "E" + Math.floor(Math.random() * 6)
        const confidence = 0.6 + Math.random() * 0.4
        resJson = {
          classification: { label: demoLabel, confidence },
          waveforms: emptyResult.waveforms,
          metrics: emptyResult.metrics,
          distribution: emptyResult.distribution,
        }
      }
      setResult(resJson)
    } finally {
      setRunning(false)
    }
  }

  if (!result) {
    return (
      <main className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-950 dark:to-slate-900 flex items-center justify-center p-4">
        <Card className="w-full max-w-2xl shadow-lg">
          <CardHeader className="border-b">
            <CardTitle className="text-3xl">RLC Fault Detection</CardTitle>
            <CardDescription className="text-base mt-2">
              Enter a SPICE netlist to classify faults using SVM analysis
            </CardDescription>
          </CardHeader>
          <CardContent className="pt-6 space-y-6">
            <div className="space-y-2">
              <label className="block text-sm font-medium">SPICE Netlist</label>
              <textarea
                value={netlist}
                onChange={(e) => setNetlist(e.target.value)}
                className="w-full h-40 p-3 border rounded-lg font-mono text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                placeholder="Paste your netlist here..."
              />
            </div>

            <div className="flex gap-3">
              <Button onClick={handleClassify} disabled={running || !netlist.trim()} size="lg" className="flex-1">
                {running ? "Classifying..." : "Classify Fault"}
              </Button>
              <Button onClick={() => setNetlist(exampleNetlist)} variant="outline" size="lg">
                Load Example
              </Button>
            </div>

            <div className="pt-4 text-xs text-muted-foreground border-t">
              <p>
                This app trains an SVM on waveforms from a reference RLC circuit to identify component faults (E0–E5).
              </p>
            </div>
          </CardContent>
        </Card>
      </main>
    )
  }

  const effective = result && typeof result === "object" ? result : emptyResult
  const classLabel = effective.classification?.label || "N/A"
  const confidence = effective.classification?.confidence || 0

  return (
    <main className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-950 dark:to-slate-900 p-4">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header with back button and result */}
        <div className="flex items-center justify-between">
          <Button onClick={() => setResult(null)} variant="outline" size="sm">
            ← New Classification
          </Button>
          <div className="text-right">
            <p className="text-sm text-muted-foreground">Classification Result</p>
            <p className="text-2xl font-bold">
              {classLabel}{" "}
              <span className="text-sm text-muted-foreground">({(confidence * 100).toFixed(1)}% confidence)</span>
            </p>
          </div>
        </div>

        {/* Waveforms */}
        <Card>
          <CardHeader>
            <CardTitle>Waveforms Analysis</CardTitle>
            <CardDescription>Input and output signals across R2 and C1</CardDescription>
          </CardHeader>
          <CardContent>
            <WaveformViewer waveforms={effective.waveforms} />
          </CardContent>
        </Card>

        {/* Distribution and Metrics */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <Card>
            <CardHeader>
              <CardTitle>Training Distribution</CardTitle>
              <CardDescription>V0 (capacitor) signal distribution</CardDescription>
            </CardHeader>
            <CardContent>
              <DistributionPlot data={effective.distribution} />
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Performance Metrics</CardTitle>
              <CardDescription>Model evaluation results</CardDescription>
            </CardHeader>
            <CardContent>
              <PerformanceMetrics metrics={effective.metrics} />
            </CardContent>
          </Card>
        </div>

        {/* Download section */}
        <Card>
          <CardHeader>
            <CardTitle>Export Data</CardTitle>
          </CardHeader>
          <CardContent className="flex gap-3">
            <Button variant="outline">Download Waveforms (CSV)</Button>
            <Button variant="outline">Download Metrics (CSV)</Button>
          </CardContent>
        </Card>
      </div>
    </main>
  )
}
